    private async Task AssertTaskVisualSlotsAsync(CombatState live,Player player)
    {
        SetStage("task_visual_slots");
        for(int i=0;i<3;i++)await NGame.Instance!.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
        var slots=TaskVisualSlotProof.Slots();var cards=player.PlayerCombatState!.AllPiles.SelectMany(p=>p.Cards).ToArray();
        var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();int rootHp=parent.State.GetCreature(player.Creature).CurrentHp;
        string Stamp(CombatPredictionSimulator sim)=>DescribeContinuationContractState(sim,root,player);
        string parentBefore=Stamp(parent),liveBefore=ContinuationStamp.CaptureLive(live).StateText;
        var snapshots=live.Enemies.Select(e=>CaptureActual(live,player,e)).ToArray();var bindings=new List<object>();int invoked=0,refused=0;
        foreach(var card in cards)
            foreach(var slot in slots)
            {
                var proof=TaskVisualSlotProof.Inspect(card.GetType(),slot);bindings.Add(new{cardType=card.GetType().FullName,proof});
                if(!proof.InvocationOnlyConstantLeaf){refused++;continue;}
                object?[] arguments=slot.GetParameters().Length==0?[]:[card,AutoPlayType.None];
                bool actual=(bool)slot.Invoke(card,arguments)!;
                if(actual!=proof.Expected)throw new InvalidOperationException("Actual virtual-slot constant value differed.");
                invoked++;
            }
        for(int i=0;i<snapshots.Length;i++)AssertSnapshotEqual(CaptureActual(live,player,live.Enemies[i]),snapshots[i],"VisualConstantSlots","InvocationOnly");
        if(Stamp(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore)throw new InvalidOperationException("Constant slot invocation changed captured state/history/RNG.");
        const BindingFlags flags=TaskVisualSlotProof.Flags;_taskVisualUnknownCalls=0;var cases=new List<object>();
        void Reject(string name,Type type,MethodInfo slot,string reason)
        {
            for(int i=0;i<2;i++)
            {
                var proof=TaskVisualSlotProof.Inspect(type,slot);
                if(proof.InvocationOnlyConstantLeaf||proof.Reason!=reason)throw new InvalidOperationException("Unknown visual slot admitted: "+name+":"+JsonSerializer.Serialize(proof));
                cases.Add(new{name,boundary=i==0?"prospective-root":"prospective-live",proof,productionIntegrated=false});
            }
        }
        Reject("external-override",typeof(TaskVisualUnknownOverride),slots[2],"unreviewed-method-binding");
        var hidden=(CardModel)RuntimeHelpers.GetUninitializedObject(typeof(TaskVisualHiddenGetter));
        var hiddenProof=TaskVisualSlotProof.Inspect(hidden.GetType(),slots[0]);
        bool? hiddenActual=hiddenProof.InvocationOnlyConstantLeaf?(bool)slots[0].Invoke(hidden,null)!:null;
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/visual-slot-binding-proof-20261008/native-checkpoint.json",
            JsonSerializer.Serialize(new{cards=cards.Length,bindings,invoked,refused,hiddenProof,hiddenActual,unknownCalls=_taskVisualUnknownCalls}));
        if(!hiddenProof.InvocationOnlyConstantLeaf||hiddenActual!=hiddenProof.Expected||_taskVisualUnknownCalls!=0)
            throw new InvalidOperationException("Hidden virtual slot diagnostic: "+JsonSerializer.Serialize(new{hiddenProof,hiddenActual,unknownCalls=_taskVisualUnknownCalls}));
        var harmony=new Harmony("combatsolver.testing.task-visual-slots");var prefix=typeof(UnattendedTestRunner).GetMethod(nameof(TaskVisualUnknownPrefix),flags)!;
        foreach(var slot in slots)
        {
            try{harmony.Patch(slot,prefix:new HarmonyMethod(prefix));Reject("patched-slot-"+slot.Name,cards[0].GetType(),slot,"unknown-patch");}
            finally{harmony.Unpatch(slot,HarmonyPatchType.All,harmony.Id);}
        }
        if(_taskVisualUnknownCalls!=0)throw new InvalidOperationException("Visual slot inspection executed unknown override/patch.");
        var frozen=cards.SelectMany(card=>slots.Select(slot=>TaskVisualSlotProof.Inspect(card.GetType(),slot)))
            .First(p=>p.InvocationOnlyConstantLeaf);
        var children=Enumerable.Range(0,16).Select(_=>parent.Fork()).ToArray();
        var holder=MegaCrit.Sts2.Core.Nodes.Combat.NPlayerHand.Instance!.Holders.First(h=>h.CardNode is not null);
        var node=holder.CardNode!;var field=node.GetType().GetField("_model",flags)!;object oldModel=field.GetValue(node)!;
        var replacement=cards.First(c=>!ReferenceEquals(c,oldModel));field.SetValue(node,replacement);
        try
        {
            await Task.WhenAll(children.Select(child=>Task.Run(()=>
            {
                using var isolation=SimulationNotificationIsolation.Enter();
                if(!frozen.InvocationOnlyConstantLeaf||Stamp(child)!=parentBefore)throw new InvalidOperationException("Frozen visual evidence changed with live UI model.");
                child.Damage(player.Creature,1,ValueProp.Unblockable|ValueProp.Unpowered,null);
