                    throw new InvalidOperationException("Owned visual proof damage/Fork differed.");
            })));
        }
        finally{field.SetValue(node,oldModel);}
        if(Stamp(parent)!=parentBefore||ContinuationStamp.CaptureLive(live).StateText!=liveBefore||_taskVisualUnknownCalls!=0)
            throw new InvalidOperationException("Visual-slot branch fixture changed parent/live.");
        var publishedSlotPatches=slots.Select(slot=>new{slot=slot.ToString(),patches=Harmony.GetPatchInfo(slot)?.Prefixes
            .Concat(Harmony.GetPatchInfo(slot)!.Postfixes).Concat(Harmony.GetPatchInfo(slot)!.Transpilers).Concat(Harmony.GetPatchInfo(slot)!.Finalizers)
            .Select(p=>new{p.owner,method=p.PatchMethod.ToString(),type=p.PatchMethod.DeclaringType!.FullName,mvid=p.PatchMethod.Module.ModuleVersionId}).ToArray()});
        var output=new{cards=cards.Length,slots=slots.Length,bindings,publishedSlotPatches,nativeConstantInvocations=invoked,currentUnprovedRefusals=refused,cases,
            hiddenSameNameSlotProof=hiddenProof,hiddenSameNameNativeCalls=1,unknownInspectionOverridePatchCalls=_taskVisualUnknownCalls,
            nativeLegacySnapshotComparisons=snapshots.Length,precreatedChildren=16,ownedDamageActions=16,perChildSecondGenerationFork=1,
            wholeVisualCertificate=false,wholeHealthCertificate=false,rootLiveProductionIntegrated=false,productionPrunes=0,searchStarted=false};
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/visual-slot-binding-proof-20261008/native-details.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
        _completedChecks.Add("TaskVisualSlots:ActualVirtualBinding:ConstantInvocations:HiddenNamePreservesBaseSlot:UnknownRefusals:16OwnedDamageForks:NoWholeCertificate");
