using System.Text.Json;
using Mono.Cecil;
using Mono.Cecil.Cil;
var source=JsonDocument.Parse(File.ReadAllText(args[0]));
using var module=ModuleDefinition.ReadModule(args[1]);
IEnumerable<TypeDefinition> Walk(IEnumerable<TypeDefinition> types){foreach(var t in types){yield return t;foreach(var n in Walk(t.NestedTypes))yield return n;}}
var all=Walk(module.Types).ToArray();var defs=all.SelectMany(t=>t.Methods).ToDictionary(m=>m.FullName);
var rows=new List<object>();
foreach(var target in source.RootElement.GetProperty("targets").EnumerateArray().Select(x=>x.GetString()!))
{
 if(!defs.TryGetValue(target,out var m))throw new InvalidOperationException("Unresolved actual target: "+target);
 rows.Add(new{target,m.IsVirtual,m.IsFinal,m.IsStatic,m.IsNewSlot,m.HasBody,declaringType=m.DeclaringType.FullName,token=m.MetadataToken.ToInt32(),
 instructions=m.HasBody?m.Body.Instructions.Select(i=>new{offset=i.Offset,opcode=i.OpCode.Name,operand=i.Operand?.ToString()}).ToArray():[],
 directTargets=m.HasBody?m.Body.Instructions.Where(i=>i.Operand is MethodReference).Select(i=>((MethodReference)i.Operand).FullName).ToArray():[]});
}
var output=new{gameMvid=module.Mvid,targetCount=rows.Count,rows,scope="Actual static target definition metadata only. Opcode callvirt can target nonvirtual methods. No receiver binding, callback, future reachability or healing safety certificate."};
File.WriteAllText(args[2],JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine("METADATA_TARGETS "+rows.Count);

