using System.Reflection;
using MegaCrit.Sts2.Core.Models;
using HarmonyLib;

namespace CombatSolver;
internal static class TaskVisualSlotProof
{
    internal const BindingFlags Flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly;
    internal sealed record Binding(bool InvocationOnlyConstantLeaf,string Reason,string Receiver,string Slot,string? Resolved,
        bool? Expected,string? Il,bool WholeHealthCertificate=false);
    internal static bool Patched(MethodBase method)
    {var p=Harmony.GetPatchInfo(method);return p is not null&&p.Prefixes.Count+p.Postfixes.Count+p.Transpilers.Count+p.Finalizers.Count!=0;}
    internal static MethodInfo[] Slots()=>[
        typeof(CardModel).GetProperty("ShouldGlowGoldInternal",Flags)!.GetMethod!,
        typeof(CardModel).GetProperty("ShouldGlowRedInternal",Flags)!.GetMethod!,
        typeof(CardModel).GetProperty("IsPlayable",Flags)!.GetMethod!,
        typeof(AbstractModel).GetMethod("ShouldPlay",Flags)!];
    internal static Binding Inspect(Type receiver,MethodInfo slot)
    {
        Binding Refuse(string reason,MethodInfo? resolved=null,string? il=null)=>new(false,reason,receiver.FullName!,slot.ToString()!,resolved?.DeclaringType?.FullName+"."+resolved?.Name,null,il);
        if(!slot.IsVirtual||slot.IsStatic||!slot.DeclaringType!.IsAssignableFrom(receiver))return Refuse("invalid-slot-or-receiver");
        MethodInfo key=slot.GetBaseDefinition();MethodInfo? target=null;
        for(Type? t=receiver;t is not null;t=t.BaseType)
        {
            var matches=t.GetMethods(Flags).Where(m=>m.IsVirtual&&!m.IsStatic&&m.GetBaseDefinition()==key).ToArray();
            if(matches.Length>1)return Refuse("ambiguous-slot");
            if(matches.Length==1){target=matches[0];break;}
        }
        if(target is null||target.IsAbstract)return Refuse("missing-slot-body",target);
        if(slot.Module.ModuleVersionId!=new Guid("8a76776c-0ce1-4d4f-90bd-8cce653dad8e")
            ||target.Module.ModuleVersionId!=slot.Module.ModuleVersionId)return Refuse("unreviewed-method-binding",target);
        if(Patched(slot)||Patched(target))return Refuse("unknown-patch",target);
        var body=target.GetMethodBody();var il=body?.GetILAsByteArray();
        if(target.ReturnType!=typeof(bool)||body is null||body.LocalVariables.Count!=0||body.ExceptionHandlingClauses.Count!=0||il is not [0x16 or 0x17,0x2a])
            return Refuse("nonconstant-body",target,il is null?null:Convert.ToHexString(il));
        return new(true,"exact-bound-constant-body",receiver.FullName!,slot.ToString()!,target.DeclaringType!.FullName+"."+target.Name,il[0]==0x17,Convert.ToHexString(il));
    }
}

