private static T ApplyLastOverride<T, TCapability>(CardModel card, string surface, T current, Func<TCapability, T?> getValue) where T : struct where TCapability : class
{
	T val = current;
	bool flag = false;
	T val2 = default(T);
	TCapability winningSource = null;
	foreach (TCapability capability in GetCapabilities<TCapability>(card))
	{
		T? value = null;
		TryRun(capability, card, surface, delegate
		{
			value = getValue(capability);
		});
		if (value.HasValue)
		{
			if (flag)
			{
				ModelCapabilityDiagnostics.WarnSurfaceConflict(surface, (AbstractModel)(object)card, winningSource, val2, capability, value.Value);
			}
			val = value.Value;
			val2 = val;
			winningSource = capability;
			flag = true;
		}
	}
	return val;
}

private static IEnumerable<TCapability> GetCapabilities<TCapability>(CardModel card) where TCapability : class
{
	return ModelCapabilityHost.GetCapabilities<TCapability>((AbstractModel)(object)card);
}

