private static void TryRun<TCapability>(TCapability capability, CardModel card, string surface, Action action) where TCapability : class
{
	try
	{
		action();
	}
	catch (Exception ex)
	{
		LogFailure(capability, card, surface, ex);
	}
}

private static void LogFailure<TCapability>(TCapability capability, CardModel card, string surface, Exception ex) where TCapability : class
{
	ModelCapabilityDiagnostics.WarnFailure(surface, (AbstractModel)(object)card, capability, ex);
}
